SELECT 'dependencies',tc.table_name,kcu.column_name,ccu.table_name FROM information_schema.table_constraints tc JOIN information_schema.key_column_usage kcu ON tc.constraint_name=kcu.constraint_name AND tc.constraint_schema=kcu.constraint_schema JOIN information_schema.constraint_column_usage ccu ON ccu.constraint_name=tc.constraint_name AND ccu.constraint_schema=tc.constraint_schema WHERE tc.constraint_type='FOREIGN KEY' AND ccu.table_name IN ('criteria','compliances','evidence');
SELECT 'owners',a."surveyId",a."surveyorId",count(*),count(*) FILTER(WHERE a."scoreId" IS NOT NULL) FROM "complianceAssessments" a JOIN compliances co USING("complianceId") JOIN criteria c USING("criterionId") WHERE c."standardId"=1 GROUP BY a."surveyId",a."surveyorId";
SELECT 'summations',"surveyId","surveyorId" FROM "surveyorStandardSummaries" WHERE "standardId"=1;
SELECT 'assignment',to_jsonb(a) FROM "surveyStandardAssignments" a WHERE "standardId"=1;
